#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Values live here, not in .env — pod IPs are per-session scratch and .env.* is
# already gitignored. Set before any write_env call.
ENV_FILE=".env.runpod"

# Restore values captured on earlier runs. Without this, START_AT=N skips the
# stages whose `ask` calls define $GPU_POD_HOST etc, and the first use of one
# dies on `set -u` -- making the resume path useless exactly when it is needed.
if [[ -f "$ENV_FILE" ]]; then
  set -a; . "$ENV_FILE"; set +a
fi

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
REPO_URL="https://github.com/KRMeeag/second-vision-ai.git"
STAGING="${REPO_ROOT}/dataset/staging"
REMOTE_STAGING="/workspace/staging_v3"
REPO_ON_POD="/workspace/second-vision-ai"
REMOTE_PROJECT="/workspace/runs_v3"

# Scratch for the check scripts the gates run. They are written to FILES rather
# than passed as heredocs for a specific reason: a heredoc attached to `gate` is
# consumed by the first attempt, so the retry inside gate's loop would hand the
# child an empty stdin -- python would read an empty program and EXIT 0, turning
# a failing gate into a passing one on the second try. Files are re-runnable.
WIZ_TMP="$(mktemp -d)"
trap 'rm -rf "$WIZ_TMP"' EXIT

# All three arms are uploaded even though only ARM trains today. Staging them
# from ONE build is what makes the shared yardstick real rather than hoped for:
# pre-flight hashes val/test label CONTENTS across every arm present and proves
# they are identical, which is what licenses comparing an arm trained next month
# to one trained today. 16 MB total -- there is no reason to be clever here.
ARMS=(v3p v3l v3s)

# Which arm trains in THIS run. Permissive alone is the default (DEC-144
# addendum): it is the agreement-boundary question the recovery work was about,
# with strict and loose bracketing it. Adding an arm later needs no new upload:
#     ARM=v3l START_AT=3 scripts/train/runpod_v3_wizard.sh
ARM="${ARM:-v3p}"
case "$ARM" in v3p|v3l|v3s) ;; *) echo "ARM must be v3p, v3l or v3s (got $ARM)"; exit 2 ;; esac
case "$ARM" in
  v3p) ARM_LABEL="PERMISSIVE"; ARM_BOXES="118,279" ;;
  v3l) ARM_LABEL="LOOSE";      ARM_BOXES="140,801" ;;
  v3s) ARM_LABEL="STRICT";     ARM_BOXES="113,965" ;;
esac

TOTAL_STAGES=10

# ── authored helpers ──────────────────────────────────────────────────────

# _at — support resuming: START_AT=9 ./runpod_v3_wizard.sh replays nothing
# before stage 9. Training runs for ~3.2 h; being forced to click through eight
# stages to reach the retrieve-and-terminate half would make that half optional,
# and it is the half with the irreversible action in it.
_at() { [[ "$_STAGE_INDEX" -ge "${START_AT:-1}" ]]; }

# gate "desc" cmd... — run a check and REFUSE to advance until it passes.
# This is the entire reason this wizard exists rather than a document. A runbook
# can tell you to pull results before terminating a pod; only a gate can stop you.
gate() {
  local desc="$1"; shift
  while true; do
    if "$@"; then
      printf '  %s✓ %s%s\n' "$GREEN" "$desc" "$RESET"
      return 0
    fi
    printf '\n'; warn "$desc — FAILED"
    say "Fix the problem above, then press Enter to re-check."
    note "Ctrl-C aborts. Resume later with:  START_AT=${_STAGE_INDEX} $0"
    pause "Press Enter to re-check"
  done
}

# ── talking to a pod over a lossy path ────────────────────────────────────
# RunPod's network is not reliable and the failure is not graceful. A euro-3
# pod measured 36.7% ICMP loss on 2026-10-18 with a clean 1500-byte path MTU
# and an idle, healthy pod at the far end: plain loss, not fragmentation and
# not load. TCP survives it, SSH does not. A key-exchange packet that drops
# leaves the client parked at "expecting SSH2_MSG_KEX_ECDH_REPLY" with no
# application-level timeout to end it, which surfaces as the "Connection to
# <ip> port <port> timed out" that looks like the pod is gone when it is not.
#
# ConnectTimeout does NOT cover this -- it bounds the TCP connect only, which
# is why raising it never helped. What does:
#   ConnectionAttempts   ssh re-sends a SYN that dropped, before giving up
#   ServerAliveInterval  strands die in ~15 s instead of hanging for minutes
#   retry on rc 255      ssh's own transport failures get another go
# Measured on that path: ~60% of single attempts succeed, so 5 tries makes a
# lost call a near-impossibility while adding nothing when the link is clean.
SSH_OPTS=(
  -o StrictHostKeyChecking=accept-new
  -o ConnectTimeout=15
  -o ConnectionAttempts=3
  -o ServerAliveInterval=5
  -o ServerAliveCountMax=3
)
SSH_TRIES="${SSH_TRIES:-5}"

# _ssh_retry tries -- cmd... — retry ONLY on ssh transport failure (rc 255).
# The distinction matters: a remote command that exits non-zero has actually
# run and its status is a real answer, so retrying it would re-run work and
# could turn a clean failure into a mess. ssh reserves 255 for its own errors,
# so that is the only code retried here. (A remote command exiting 255 itself
# is indistinguishable and would be retried -- rare, and harmless for the
# read-only and idempotent commands this wizard sends.)
_ssh_retry() {
  local tries="$1"; shift
  local n=1 rc=0
  while :; do
    "$@" && return 0
    rc=$?
    [[ $rc -ne 255 ]] && return "$rc"
    [[ $n -ge $tries ]] && return "$rc"
    printf '  %sssh transport failed (%s/%s) — retrying in %ss%s\n' \
      "$DIM" "$n" "$tries" "$((n * 3))" "$RESET" >&2
    sleep "$((n * 3))"
    n=$((n + 1))
  done
}

# podssh cmd... — run a command on the GPU pod over the direct TCP SSH.
# A function, not a POD="-p ... -i ..." variable: in bash an unquoted $POD
# word-splits into separate arguments, but zsh passes it as ONE argument and ssh
# then reads everything after -p as the port ("Bad port"). "$@" is clean in both.
podssh() {
  _ssh_retry "$SSH_TRIES" \
    ssh -p "$GPU_POD_PORT" -i "$SSH_KEY" "${SSH_OPTS[@]}" \
        root@"$GPU_POD_HOST" "$@"
}

# podsync SRC... DEST — rsync over the same path, resumable. Either side may be
# root@host:path. Replaces scp everywhere in this wizard because scp restarts a
# broken transfer from byte zero, and on a 37%-loss link a retried scp can lose
# more work than it completes.
#
# --partial-dir (not --append-verify) is the safe resume: rsync keeps the partial
# aside and uses it as a delta basis on the next attempt, re-sending only the
# blocks that differ. --append-verify would be faster but assumes the partial is
# a prefix of the source and SKIPS any file whose destination size already
# matches -- which would silently decline to re-pull a result file that changed
# without changing length.
podsync() {
  local n=1
  while :; do
    rsync -az --partial --partial-dir=.rsync-partial --timeout=60 \
          -e "ssh -p $GPU_POD_PORT -i $SSH_KEY ${SSH_OPTS[*]}" "$@" && return 0
    [[ $n -ge $SSH_TRIES ]] && return 1
    printf '  %stransfer interrupted (%s/%s) — resuming in %ss%s\n' \
      "$DIM" "$n" "$SSH_TRIES" "$((n * 5))" "$RESET" >&2
    sleep "$((n * 5))"
    n=$((n + 1))
  done
}

# _wait_for_arm — block until $ARM finishes, then return 0. Returns 1 if the
# driver died without producing a marker, 2 if the cap elapsed.
#
# The whole point is that a poll which cannot reach the pod proves nothing: on
# this link an unreachable pod is the expected case, not evidence about the run.
# So only two things count as signal -- the arm's .done marker, and the driver
# being absent. And "driver absent, no marker" must be seen 3 polls running
# before it is believed, because run_v3.sh is legitimately between phases (and
# between arms) for stretches with no training process alive.
_wait_for_arm() {
  local interval="${POLL_SECONDS:-300}" cap="${WAIT_HOURS:-14}"
  local deadline=$(( SECONDS + cap * 3600 )) gone=0 out last=""
  printf '\n'
  note "polling every $((interval / 60)) min — Ctrl-C is safe, resume with START_AT=9 $0"
  while :; do
    out=$(podssh "test -f $REMOTE_PROJECT/$ARM.done && echo MARKER; \
                  pgrep -f 'train_one_arm.py|scripts/train/train.py' >/dev/null && echo ALIVE; \
                  tail -1 $REMOTE_PROJECT/STATUS 2>/dev/null" 2>/dev/null) || out="UNREACHABLE"

    if [[ "$out" == *MARKER* ]]; then
      printf '\n  %s✓ %s finished — marker present on the pod%s\n' \
        "$GREEN" "$ARM" "$RESET"
      return 0
    fi

    if [[ "$out" == "UNREACHABLE" ]]; then
      gone=0                         # no information, so no conclusion
    elif [[ "$out" == *ALIVE* ]]; then
      gone=0
    else
      gone=$((gone + 1))
      if [[ $gone -ge 3 ]]; then
        printf '\n'
        warn "no training process and no $ARM.done marker, 3 polls running."
        warn "The driver has stopped. Read the log before spending more:"
        note "  podssh \"tail -40 $REMOTE_PROJECT/logs/driver.log\""
        return 1
      fi
    fi

    # Only reprint when the status line actually moved, so an overnight wait
    # leaves a readable trail instead of hundreds of identical lines.
    local tail_line="${out//MARKER/}"; tail_line="${tail_line//ALIVE/}"
    tail_line="$(printf '%s' "$tail_line" | tr -d '\n' | cut -c1-70)"
    if [[ "$tail_line" != "$last" ]]; then
      printf '  %s[%s] %s%s\n' "$DIM" "$(date +%H:%M)" "${tail_line:-waiting}" "$RESET"
      last="$tail_line"
    fi

    if [[ $SECONDS -ge $deadline ]]; then
      printf '\n'; warn "gave up after ${cap} h — the pod is still up and still charging."
      return 2
    fi
    sleep "$interval"
  done
}

RETRIEVED_OK=0   # set to 1 only when results are verified on this Mac; gates the terminate

# ──────────────────────────────────────────────────────────────────────────

banner "Second Vision — v3 training on RunPod (${ARM_LABEL}, ${ARM_BOXES} train boxes)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pre-flight on this Mac — pushed, keyed, and the arms verified"
if _at; then
say "Everything checked here is free. Everything after stage 3 costs GPU time."

step "The pod clones the repo from GitHub — anything uncommitted will not exist there."
if ! git -C "$REPO_ROOT" diff --quiet || ! git -C "$REPO_ROOT" diff --cached --quiet \
   || [ -n "$(git -C "$REPO_ROOT" ls-files --others --exclude-standard)" ]; then
  warn "You have uncommitted or untracked files:"
  git -C "$REPO_ROOT" status --short | sed 's/^/    /'
  say "The whole v3 driver lives in the repo, so scripts/train/*.py and *.sh in"
  say "particular MUST be pushed — setup_pod_v3.sh checks for them by name and"
  say "refuses to continue without them."
  pause "Commit and push in another terminal, then press Enter"
fi
say "Fetching origin so the push check compares against the real remote..."
git -C "$REPO_ROOT" fetch origin --quiet || warn "fetch failed — push check may be stale"
gate "local branch is pushed to origin" bash -c \
  "[ -z \"\$(git -C '$REPO_ROOT' log --oneline origin/main..HEAD 2>/dev/null)\" ]"

printf '\n'
say "Checking the three staged arm archives..."
# Verifies the ARCHIVES, not the script that wrote them. An earlier version of
# stage_v3_arms.py built each data.yaml by slicing lines and dropped the `names:`
# key itself, emitting something yaml.safe_load refuses outright -- all three arms
# were unloadable and nothing downstream could have trained on them. This parses
# what is actually inside each tarball.
cat > "$WIZ_TMP/check_arms.py" <<'PY'
import sys, tarfile, yaml
from pathlib import Path
staging, repo = Path(sys.argv[1]), Path(sys.argv[2])
sys.path.insert(0, str(repo))
from scripts.utils.config_loader import CANONICAL_NAMES, EXPECTED_NC
ok = True
for arm in ("v3p", "v3l", "v3s"):
    t = staging / f"{arm}.tar.gz"
    if not t.is_file():
        print(f"    {arm}: MISSING {t}")
        ok = False
        continue
    try:
        with tarfile.open(t) as tf:
            d = yaml.safe_load(tf.extractfile(f"{arm}/data.yaml").read())
            names = [d["names"][i] for i in sorted(d["names"])]
            n_lab = sum(1 for m in tf.getnames() if m.startswith(f"{arm}/labels/"))
            if names != CANONICAL_NAMES or d["nc"] != EXPECTED_NC:
                print(f"    {arm}: schema mismatch, nc={d.get('nc')} names={names}")
                ok = False
            elif n_lab != 43170:
                print(f"    {arm}: {n_lab} label files, expected 43,170")
                ok = False
            else:
                print(f"    {arm}: OK  nc={d['nc']}  {n_lab:,} labels  "
                      f"{t.stat().st_size / 1e6:.1f} MB")
    except Exception as e:
        print(f"    {arm}: {type(e).__name__}: {e}")
        ok = False
if not ok:
    print("\n    Re-stage with:  python3 scripts/train/stage_v3_arms.py --apply")
sys.exit(0 if ok else 1)
PY
gate "all three arms staged, data.yaml parses, schema matches the repo" \
  python3 "$WIZ_TMP/check_arms.py" "$STAGING" "$REPO_ROOT"

printf '\n'
ask SSH_KEY "Path to your SSH private key [~/.ssh/id_ed25519]:"
[[ -z "$SSH_KEY" ]] && SSH_KEY="$HOME/.ssh/id_ed25519"
SSH_KEY="${SSH_KEY/#\~/$HOME}"
gate "SSH private key exists" test -f "$SSH_KEY"
write_env SSH_KEY "$SSH_KEY"
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "RunPod — add your SSH public key (BEFORE any pod exists)"
if _at; then
warn "RunPod injects public keys at pod START. A key added afterwards needs a restart."
say "Your public key:"
if [[ -f "${SSH_KEY}.pub" ]]; then
  printf '\n'; sed 's/^/    /' "${SSH_KEY}.pub"; printf '\n'
else
  warn "No ${SSH_KEY}.pub found — deriving it from the private key:"
  printf '\n'
  ssh-keygen -y -f "$SSH_KEY" | sed 's/^/    /' \
    || warn "ssh-keygen could not derive the public key (passphrase-protected?)"
  printf '\n'
fi
open_url "https://console.runpod.io/user/settings"
step "Settings → SSH Public Keys → paste the key above → Update."
note "Already there from the v2 run? Then nothing to do — just press Enter."
pause "Press Enter once the key is saved"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Deploy the RTX 4090 — same datacenter, EXISTING volume"
if _at; then
say "No upload stage this time. The 109,034 images are already on the volume from"
say "the v2 run; the arms are 16 MB of labels that point at them."
printf '\n'
if [[ -n "${RUNPOD_DATACENTER:-}" ]]; then
  note "From your v2 run, the volume lives in: ${RUNPOD_DATACENTER}"
else
  ask RUNPOD_DATACENTER "Which datacenter holds your network volume? (e.g. EU-RO-1):"
  write_env RUNPOD_DATACENTER "$RUNPOD_DATACENTER"
fi
warn "A pod can only mount a volume in its OWN datacenter."
open_url "https://console.runpod.io/deploy"
# No apostrophe in the :- default. Bash parses quote characters INSIDE a
# parameter expansion even when the whole word is double-quoted, so a stray
# "volume's" there opens a single quote that runs to end of file.
step "Deploy an RTX 4090 in ${RUNPOD_DATACENTER:-the datacenter holding your volume} (A6000 is the fallback)."
step "Attach the EXISTING network volume — do not create a new one."
step "Use a PyTorch template: it ships a CUDA-matched torch, and that matters."
step "Expose TCP port 22, and HTTP port 6006 if you want live TensorBoard."
note "requirements-train.txt deliberately does not name torch. The template's build"
note "is CUDA-matched; letting pip resolve torch usually swaps in a CPU-only wheel,"
note "and training then runs ~50x slower and reports NO error at all."
printf '\n'
warn "Use 'SSH over exposed TCP' from the Connect panel — NOT ssh.runpod.io."
warn "The proxy form is a restricted shell and scp does not work through it."
ask GPU_POD_HOST "Pod IP address:"
ask GPU_POD_PORT "Pod SSH port:"
write_env GPU_POD_HOST "$GPU_POD_HOST"
write_env GPU_POD_PORT "$GPU_POD_PORT"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GATE — SSH, the volume, and the images the arms point at"
if _at; then
say "Failing here costs seconds. Failing after setup starts costs a pod session."
gate "SSH to the GPU pod works" podssh true

# Getting this wrong is silent and total: training writes three hours of weights
# to a disk that is destroyed with the pod.
gate "/workspace is the mounted network volume (not container disk)" \
  podssh "mountpoint -q /workspace || df -h /workspace | tail -1 | grep -qv overlay"
podssh "df -h /workspace | sed 's/^/    /'" || warn "could not read df (display only)"
note "If that shows an 'overlay' filesystem, the volume is NOT attached — stop and"
note "re-deploy the pod with the network volume mounted."

printf '\n'
say "The arms are label files plus text lists of ABSOLUTE image paths, every one"
say "resolving under /workspace/bundle/images. That directory is the one thing the"
say "arms cannot carry with them."
gate "/workspace/bundle/images is present and populated" \
  podssh "test -d /workspace/bundle/images && [ \"\$(ls /workspace/bundle/images | head -200 | wc -l)\" -ge 200 ]"
podssh "echo \"    bundle/images: \$(ls /workspace/bundle/images | wc -l) files\"" \
  || warn "could not count bundle/images (display only)"
note "Expected ~109,034. If this directory is gone, the volume was wiped and the"
note "5.1 GB bundle must be re-uploaded first — scripts/train/runpod_wizard.sh"
note "stages 4-8 do that, and it is a ~2.2 h job."
pause "Press Enter to continue"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GATE — upload all three arms, checksum-verified on the pod"
if _at; then
say "All three, even though only ${ARM_LABEL} trains today. Staging them from one"
say "build is what makes the comparison valid later: pre-flight hashes the val and"
say "test label CONTENTS across every arm present and requires them identical."
note "16 MB total. Adding an arm next month then costs its own 3 h and nothing else."
printf '\n'
podssh "mkdir -p $REMOTE_STAGING" || warn "could not create $REMOTE_STAGING"
for a in "${ARMS[@]}"; do
  say "uploading ${a}.tar.gz ..."
  podsync "$STAGING/${a}.tar.gz" "root@${GPU_POD_HOST}:${REMOTE_STAGING}/" \
    || warn "upload of ${a}.tar.gz failed — the gate below will catch it"
done
printf '\n'
# Compare the sha256 computed on BOTH sides. A truncated transfer produces a
# tarball that still opens and is simply missing labels from the end.
cat > "$WIZ_TMP/check_upload.sh" <<'SH'
#!/usr/bin/env bash
# args: STAGING REMOTE_STAGING SSH_KEY HOST PORT ARMS...
staging="$1"; remote="$2"; key="$3"; host="$4"; port="$5"; shift 5
for a in "$@"; do
  L=$(shasum -a 256 "$staging/${a}.tar.gz" | awk '{print $1}')
  # Retried, and for the same reason as podssh: on a lossy path an unreachable
  # pod returns an empty $R, which would read as a checksum mismatch and send
  # the human chasing a corrupt upload that is actually fine.
  R=""
  for _try in 1 2 3 4 5; do
    R=$(ssh -p "$port" -i "$key" -o StrictHostKeyChecking=accept-new \
        -o ConnectTimeout=15 -o ConnectionAttempts=3 \
        -o ServerAliveInterval=5 -o ServerAliveCountMax=3 "root@${host}" \
        "sha256sum ${remote}/${a}.tar.gz 2>/dev/null | cut -d' ' -f1") && break
    sleep $((_try * 3))
  done
  if [ -z "$R" ]; then
    printf '    %s: could not reach the pod to verify after 5 tries\n' "$a"
    exit 1
  fi
  if [ "$L" != "$R" ]; then
    printf '    %s: MISMATCH  local=%s  pod=%s\n' "$a" "${L:0:16}" "${R:0:16}"
    exit 1
  fi
  printf '    %s: %s OK\n' "$a" "${L:0:16}"
done
SH
chmod +x "$WIZ_TMP/check_upload.sh"
gate "all three archives match their local sha256 on the pod" \
  "$WIZ_TMP/check_upload.sh" "$STAGING" "$REMOTE_STAGING" "$SSH_KEY" \
  "$GPU_POD_HOST" "$GPU_POD_PORT" "${ARMS[@]}"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Comet — how you check in without sitting at the laptop"
if _at; then
say "Comet is optional: training works and TensorBoard still logs locally. But it"
say "is how you watch a 3-hour run from your phone, so it is worth the minute."
printf '\n'
if [[ -n "${COMET_API_KEY:-}" ]]; then
  note "A key is already in $ENV_FILE. Press Enter to keep it."
else
  open_url "https://www.comet.com/account-settings/apiKeys"
  step "Copy your API key."
fi
ask_secret COMET_API_KEY "Comet API key:"
if [[ -n "${COMET_API_KEY:-}" ]]; then
  write_env COMET_API_KEY "$COMET_API_KEY"
  ask COMET_PROJECT_NAME "Comet project name (e.g. second-vision-v3):"
  if [[ -n "${COMET_PROJECT_NAME:-}" ]]; then
    write_env COMET_PROJECT_NAME "$COMET_PROJECT_NAME"
  else
    note "no project name — runs land in Comet's default project"
  fi
  # Persisted on the pod so a reconnect or a fresh shell still has it.
  podssh "grep -q COMET_API_KEY /root/.bashrc || echo 'export COMET_API_KEY=${COMET_API_KEY}' >> /root/.bashrc; \
          grep -q COMET_PROJECT_NAME /root/.bashrc || echo 'export COMET_PROJECT_NAME=${COMET_PROJECT_NAME:-}' >> /root/.bashrc" \
    && say "written to the pod's /root/.bashrc" || warn "could not write to the pod's /root/.bashrc"
  note "train.py AUTHENTICATES the key rather than checking the variable is set, and"
  note "prints ARMED / NOT ARMED at the start of every run. A typo'd or revoked key"
  note "otherwise reports armed and logs nothing for three hours."
else
  SKIPPED+=("Comet API key — TensorBoard still logs; check in with run_v3.sh --status")
  warn "no key given — you will check in with --status over SSH instead"
fi
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GATE — pod setup (the tried-and-tested stage 12, scripted)"
if _at; then
say "This is scripts/train/runpod_wizard.sh stage 12, lifted into a script so it"
say "can run unattended and be re-run after a pod restart. It checks the volume,"
say "installs requirements-train.txt, puts YOLO_CONFIG_DIR on the volume, pins"
say "runs_dir there, gates on CUDA + ultralytics 8.4.118, extracts all three arms,"
say "makes the images symlink, and moves any stale labels.cache aside."
printf '\n'
note "A surviving labels.cache is a correctness bug, not a stale file: ultralytics"
note "keys it on the image+label PATH LIST, not contents, so re-staged labels under"
note "identical filenames look valid and it would serve the previous arm's boxes."
printf '\n'
say "First, make sure the pod has the code..."
gate "repo present on the pod and up to date" podssh \
  "{ [ -d $REPO_ON_POD/.git ] && git -C $REPO_ON_POD pull --ff-only; } || git clone $REPO_URL $REPO_ON_POD"
printf '\n'
gate "setup_pod_v3.sh passes every check" podssh \
  "cd $REPO_ON_POD && COMET_API_KEY='${COMET_API_KEY:-}' COMET_PROJECT_NAME='${COMET_PROJECT_NAME:-}' \
   bash scripts/train/setup_pod_v3.sh"
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Launch — ${ARM_LABEL}, detached, ~3.2 h"
if _at; then
say "run_v3.sh runs pre-flight and a smoke run before it spends a single real"
say "GPU-hour, then re-execs itself under setsid and returns."
printf '\n'
note "  pre-flight  ~4 min   every staged arm verified; full label scan"
note "  smoke       ~4 min   2 epochs on 2%, then a real test-split eval"
note "  baseline    ~2 min   v2 weights on the new test labels, remapped by name"
note "  ${ARM}         ~3.0 h   ${ARM_LABEL}, ${ARM_BOXES} train boxes"
printf '\n'
warn "If pre-flight or the smoke run fails, it STOPS and nothing is spent. That is"
warn "the design: the smoke run exercises the same path that then runs for 3 hours."
printf '\n'
pause "Press Enter to launch"
podssh "cd $REPO_ON_POD && COMET_API_KEY='${COMET_API_KEY:-}' COMET_PROJECT_NAME='${COMET_PROJECT_NAME:-}' \
        bash scripts/train/run_v3.sh $ARM" || warn "launch returned non-zero — read the output above"
printf '\n'
say "Watch it from any terminal:"
printf '\n'
printf '    ssh -p %s -i %s root@%s "%s/scripts/train/run_v3.sh --status"\n' \
  "$GPU_POD_PORT" "$SSH_KEY" "$GPU_POD_HOST" "$REPO_ON_POD"
printf '    ssh -p %s -i %s root@%s "tail -f /workspace/runs_v3/logs/driver.log"\n' \
  "$GPU_POD_PORT" "$SSH_KEY" "$GPU_POD_HOST"
printf '\n'
note "Or source scripts/train/podenv.sh and use:  podssh \"...\""
printf '\n'
say "The next two stages retrieve the results and terminate the pod."
printf '\n'
say "This wizard can wait for the run itself rather than you watching it. It"
say "polls the marker file every 5 minutes and tolerates the link dropping —"
say "an unreachable poll is a lost packet, not a lost run, so it keeps waiting."
printf '\n'
note "  POLL_SECONDS=300  how often to poll      WAIT_HOURS=14  when to give up"
printf '\n'
if confirm "Wait here until ${ARM} finishes, then continue automatically?"; then
  _wait_for_arm; _wait_rc=$?
  if [[ $_wait_rc -eq 1 ]]; then
    warn "Not continuing to retrieval — the run did not finish."
    say "The pod is left up on purpose so you can read the log. Resume with:"
    printf '\n    START_AT=9 %s\n\n' "$0"
    pause "Press Enter to exit"
    exit 1
  elif [[ $_wait_rc -eq 2 ]]; then
    say "Resume whenever you like with:"
    printf '\n    START_AT=9 %s\n\n' "$0"
    pause "Press Enter to exit"
    exit 1
  fi
else
  say "Fine — come back when it is done with:"
  printf '\n'
  printf '    START_AT=9 %s\n' "$0"
  printf '\n'
  pause "Press Enter when the run has finished"
fi
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "GATE — pull the results to this Mac BEFORE terminating anything"
if _at; then
say "The volume has been cut off once before, by a lapsed balance (DEC-137). Results"
say "survive a pod, but only a copy on this laptop survives the volume."
printf '\n'
say "Current state on the pod:"
podssh "cd $REPO_ON_POD && bash scripts/train/run_v3.sh --status" 2>&1 | sed 's/^/    /' \
  || warn "could not read --status"
printf '\n'
if ! confirm "Has the run finished? (No = leave the pod up and come back)"; then
  say "Nothing touched. Resume with:  START_AT=9 $0"
  pause "Press Enter to exit"
  exit 0
fi
printf '\n'
mkdir -p "$REPO_ROOT/runs"
say "Pulling $REMOTE_PROJECT (markers, logs, result JSONs)..."
podsync -r "root@${GPU_POD_HOST}:${REMOTE_PROJECT}" "$REPO_ROOT/runs/" \
  || warn "pull of runs_v3 failed"
say "Pulling runs/detect (weights, results.csv, args.yaml, provenance, eval CSV)..."
podsync -r "root@${GPU_POD_HOST}:${REPO_ON_POD}/runs/detect" "$REPO_ROOT/runs/" \
  || warn "pull of runs/detect failed"
printf '\n'
# Two locations on purpose, and BOTH must be here: runs_v3 holds the result JSON
# the comparison reads, runs/detect holds the weights and the per-class eval the
# paper cites. Either one alone is not the run.
cat > "$WIZ_TMP/check_results.py" <<'PY'
import json, sys
from pathlib import Path
repo, arm = Path(sys.argv[1]), sys.argv[2]
ok = True
j = repo / "runs" / "runs_v3" / f"{arm}_result.json"
if not j.is_file():
    print(f"    missing {j}")
    ok = False
else:
    d = json.loads(j.read_text())
    t = d["test"]
    print(f"    {d['label']}  mAP50={t['mAP50']:.4f}  mAP50-95={t['mAP50_95']:.4f}  "
          f"P={t['precision']}  R={t['recall']}  ({d['train_hours']}h)")
    print(f"    args parity with v2 : {d['args_parity_with_v2']}")
    print(f"    criterion (DEC-122) : {d.get('criterion_verdict')}")
    print(f"    run dir on the pod  : {d['run_dir']}")
    if d.get("smoke"):
        print("    !! this is the SMOKE result, not the real run")
        ok = False
det = repo / "runs" / "detect"
w = sorted(det.glob(f"*v3_{arm}*/weights/best.pt"))
if not w:
    print(f"    no best.pt under runs/detect for {arm}")
    ok = False
else:
    print(f"    weights  : {w[0]}  ({w[0].stat().st_size / 1e6:.0f} MB)")
e = sorted(det.glob(f"*v3_{arm}*/eval_fp32_test_per_class.csv"))
if not e:
    print(f"    no per-class eval CSV under runs/detect for {arm}")
    ok = False
else:
    rows = e[0].read_text().strip().splitlines()
    print(f"    eval CSV : {e[0]}  ({len(rows) - 1} class rows)")
sys.exit(0 if ok else 1)
PY
if gate "results are on this Mac: ${ARM}_result.json, best.pt and the eval CSV" \
     python3 "$WIZ_TMP/check_results.py" "$REPO_ROOT" "$ARM"; then
  RETRIEVED_OK=1
fi
note "These land in runs/, which is gitignored — they are not for git. The tracked"
note "pointer is models/current/README.md, same as the v1 and v2 kits."
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "TERMINATE the pod — not Stop"
if _at; then
if [[ "$RETRIEVED_OK" -ne 1 ]]; then
  warn "Stage 9 did not verify the results on this Mac in this run."
  warn "Terminating now could destroy the only copy of a 3-hour run."
  if ! confirm "Terminate anyway? (No is the right answer unless you pulled them earlier)"; then
    say "Skipping termination — the pod stays up. Verify first:  START_AT=9 $0"
    pause "Press Enter to finish"
    finish
    exit 0
  fi
fi
warn "TERMINATE, do not Stop. A stopped pod keeps billing for its container disk."
say "Terminating destroys the container disk. These all survive on the volume:"
note "  /workspace/bundle            the 109,034 images"
note "  /workspace/v3p /v3l /v3s     all three arms, still laid out"
note "  /workspace/runs_v3           markers, logs, result JSONs"
note "  /workspace/second-vision-ai  the repo, including runs/detect"
say "Installed pip packages do NOT survive — expected. setup_pod_v3.sh is"
say "idempotent and reinstalls them in about two minutes on the next pod."
printf '\n'
say "So adding an arm later is a new pod plus:"
printf '\n'
printf '    ARM=v3l START_AT=3 %s\n' "$0"
printf '\n'
note "Stage 5 re-uploads the arms harmlessly — the gate just re-verifies the shas."
note "But if you RE-STAGE an arm after pre-flight has passed, clear the marker:"
note "  rm /workspace/runs_v3/preflight.done"
note "Otherwise pre-flight is skipped and the rebuilt arm goes in unverified."
printf '\n'
open_url "https://console.runpod.io/pods"
step "Find this pod → Terminate."
pause "Press Enter once terminated"
fi

finish
